/// <summary>
/// parmCustAccount method
/// </summary>
/// <param name = "_custAccount">CustAccount</param>
/// <returns>CustAccount</returns>
public CustAccount parmCustAccount(CustAccount _custAccount = CustAccount)
{
    custAccount = _custAccount;
    return custAccount;
}

/// <summary>
/// parmCreditLimitGroup
/// </summary>
/// <param name = "_creditLimitGroup">CredManCreditLimitId</param>
/// <returns>CredManCreditLimitId</returns>
[DataMemberAttribute]
public CredManCreditLimitId parmCreditLimitGroup(CredManCreditLimitId _creditLimitGroup = creditLimitGroup)
{
    creditLimitGroup = _creditLimitGroup;
    return creditLimitGroup;
}

public DataAreaId parmDataAreaId(DataAreaId _company = company)
{
    company = _company;
    return company;
}
